"""Ramvan Rush, a desktop typing chase built with Python and Tk.

Run with Python 3 and Tkinter. The artwork is embedded below the game code.
The campus and shuttle art was generated with OpenAI ImageGen.
Shuttle visual reference:
https://www.fordham.edu/student-life/department-of-transportation/ram-van-shuttle/
"""
from collections import deque
from math import ceil, cos, exp, pi, sin
from random import Random
from time import perf_counter
import tkinter as tk
from tkinter import font

WIDTH, HEIGHT = 1000, 650
STREET_TOP, CURB = 82, 483
DURATION = 72
INITIAL_GAP = 270
VAN_SPEED = 6
CREAM, INK = "#fff0da", "#160f20"
MUTED, GOLD, MINT, RED = "#c2b0c8", "#ffc269", "#81ebc7", "#ff7587"

PROMPTS = (
    "I skipped lunch to make this shuttle. Apparently, hunger is a poor substitute for leg day. The campus squirrels look better fueled.",
    "Two assignments are due at 11:59 PM. My laptop has three percent battery and excellent timing. Even the charger is missing.",
    "I packed three textbooks for one class. My backpack is pursuing a degree of its own. It has a heavier course load than I do.",
    "The driver said to be here five minutes early. I was five minutes early in a different time zone.",
    "I told my professor I was making great strides. Technically, I am making them right now.",
    "My iced coffee survived the stairs at Rose Hill. This is the strongest part of my academic record.",
    "The Ram Van has a seat with my name on it. I hope the driver is willing to check the spelling.",
    "I have a group project at Lincoln Center. My group is currently providing moral support by text.",
    "The syllabus says attendance matters. I would like to submit this sprint for partial credit.",
    "I picked the scenic route through Rose Hill. The scenery is lovely, especially when it is not moving past me at this speed.",
    "My roommate said the shuttle was right around the corner. I would like to know which corner, and whether it is still in the Bronx.",
    "The elevator stopped on every floor. I had enough time to rethink my major, but apparently not enough time to make the van.",
    "I set three alarms for this trip. The first two were optimistic, and the third was more of a formal notice.",
    "I bought a bagel for the ride. At this point, it has a better chance of seeing Lincoln Center than I do.",
    "I am wearing my fastest sneakers. Unfortunately, I chose them based on color, and the van does not appear to be impressed.",
    "I waved so the driver would see me. A professor waved back, which was nice, but nobody slowed down.",
    "My watch just congratulated me on finishing a workout. I appreciate the encouragement, but I was trying to get to class.",
    "The campus tour guide said everything was a short walk. I assume the Ram Van was parked when they wrote that part.",
    "I booked a window seat in my imagination. The rest of the reservation may require slightly more effort.",
)


class Chase:
    def __init__(self, prompts=PROMPTS):
        self.prompts = prompts
        self.round = self.index = self.correct = self.attempts = 0
        self.elapsed = self.pace = 0.0
        self.gap = INITIAL_GAP
        self.hits = deque()
        self.outcome = None

    @property
    def prompt(self):
        return self.prompts[self.round % len(self.prompts)]

    @property
    def speed(self):
        return 1.45 + 1.15 * min(18, self.pace)

    @property
    def accuracy(self):
        return round(100 * self.correct / max(1, self.attempts))

    def type_letter(self, letter):
        self.attempts += 1
        if letter != self.prompt[self.index]:
            return False
        self.correct += 1
        self.hits.append(self.elapsed)
        self.index += 1
        if self.index == len(self.prompt):
            self.round += 1
            self.index = 0
        return True

    def tick(self, dt):
        self.elapsed = min(DURATION, self.elapsed + dt)
        while self.hits and self.elapsed - self.hits[0] > 2.4:
            self.hits.popleft()
        target = len(self.hits) / 2.4
        self.pace += (target - self.pace) * (1 - exp(-dt * 5))
        self.gap -= (self.speed - VAN_SPEED) * dt
        if self.gap <= 0:
            self.gap = 0
            self.outcome = "won"
        elif self.elapsed >= DURATION:
            self.outcome = "lost"


class Game:
    def __init__(self, root):
        self.root = root
        root.title("Ramvan Rush")
        root.resizable(False, False)
        self.canvas = tk.Canvas(root, width=WIDTH, height=HEIGHT,
                                bg=INK, highlightthickness=0)
        self.canvas.pack()
        self.regular = font.Font(family="Consolas", size=-20)
        self.mono = font.Font(family="Consolas", size=-13, weight="bold")
        self.bold = font.Font(family="Arial", size=-23, weight="bold")
        self.title = font.Font(family="Arial", size=-56, weight="bold", slant="italic")
        self.small = font.Font(family="Arial", size=-15)
        self.scenery = [tk.PhotoImage(data=ARTWORK[name], format="png") for name in
                        ("rose-hill.png", "rose-hill-reverse.png")]
        self.van = tk.PhotoImage(data=ARTWORK["ram-van.png"], format="png")
        self.mode = "ready"
        self.chase = Chase()
        self.clock = self.last_frame = perf_counter()
        self.travel, self.stride = 190.0, 0.0
        self.error_until = self.flash_until = 0.0
        rng = Random(17)
        self.leaves = [(rng.randrange(1000), rng.randrange(370),
                        rng.randrange(20, 90), rng.choice(("#f8a450", "#df6647", "#eac665")))
                       for _ in range(22)]
        root.bind("<KeyPress>", self.keypress)
        root.bind("<FocusOut>", self.focus_lost)
        self.canvas.bind("<Button-1>", self.click)
        self.frame()

    def start(self):
        prompts = list(PROMPTS)
        Random().shuffle(prompts)
        self.chase = Chase(prompts)
        self.mode = "running"
        self.error_until = self.flash_until = 0.0
        self.last_frame = perf_counter()

    def keypress(self, event):
        if event.keysym == "Return":
            self.activate()
            return "break"
        if event.keysym == "Escape":
            if self.mode == "running":
                self.mode = "paused"
            elif self.mode == "paused":
                self.mode = "running"
            return "break"
        if self.mode == "running" and not event.state & 0x0004:
            if event.char and event.char.isprintable():
                now = perf_counter()
                if self.chase.type_letter(event.char):
                    self.error_until = 0.0
                    self.flash_until = now + .12
                else:
                    self.error_until = now + .30
        return "break"

    def focus_lost(self, _event):
        if self.mode == "running":
            self.mode = "paused"

    def click(self, event):
        if self.mode != "running" and 366 <= event.x <= 634 and 358 <= event.y <= 404:
            self.activate()

    def activate(self):
        if self.mode in ("ready", "won", "lost"):
            self.start()
        elif self.mode == "paused":
            self.mode = "running"

    def rect(self, *coords, color, **kwargs):
        return self.canvas.create_rectangle(*coords, fill=color, outline="", **kwargs)

    def text(self, x, y, value, color=CREAM, face=None, anchor="w", **kwargs):
        return self.canvas.create_text(x, y, text=value, fill=color,
                                       font=face or self.mono, anchor=anchor, **kwargs)

    def line(self, *coords, color, width=1):
        self.canvas.create_line(*coords, fill=color, width=width)

    def stage(self, now):
        c = self.canvas
        tile_width = self.scenery[0].width()
        position = self.travel * .78
        tile, offset = divmod(int(position), tile_width)
        for i in range(2):
            c.create_image(i * tile_width - offset, STREET_TOP,
                           image=self.scenery[(tile + i) % 2], anchor="nw")
        for x in range(-int(self.travel) % 156 - 156, WIDTH, 156):
            self.rect(x, 504, x + 78, 507, color="#8d6272")
        for x, y, rate, color in self.leaves:
            drift = (x - position * .7 - now * rate * .45) % WIDTH
            fall = STREET_TOP + (y + now * rate * .18) % 373
            c.create_polygon(drift, fall, drift + 7, fall - 2,
                             drift + 5, fall + 2, drift + 1, fall + 3, fill=color)
        gap = self.chase.gap
        runner_x = 245
        van_x = runner_x + 56 + 450 * gap / (gap + 78)
        if self.mode == "lost":
            van_x += min(730, (now + self.clock - self.finished_at) * 365)
        van_y = CURB + 6 + round(sin(self.travel / 11))
        c.create_oval(van_x + 8, van_y - 7, van_x + 283, van_y + 6, fill="#211723", outline="")
        c.create_image(van_x, van_y, anchor="sw", image=self.van)
        for ax in (54, 243):
            angle = self.travel / 11
            hub_x, hub_y = van_x + ax, van_y - 15
            self.line(hub_x - 6 * cos(angle), hub_y - 6 * sin(angle),
                      hub_x + 6 * cos(angle), hub_y + 6 * sin(angle), color="#bfb1c5", width=2)
        self.runner(runner_x, CURB + 10)
        if self.mode == "running" and self.chase.pace > 3.5:
            for i in range(9):
                x = (i * 115 - self.travel * 3.2) % 1100 - 100
                y = 353 + (i * 39) % 140
                self.line(x, y, x + 12 + self.chase.pace * 6, y - 3,
                          color="#edb495", width=2)

    def runner(self, x, ground):
        c = self.canvas
        p = self.stride
        bob = 0 if self.mode == "won" else 5 * abs(sin(p))
        y = ground - 58 - bob
        c.create_oval(x - 50, ground - 5, x + 51, ground + 5, fill="#271c2c", outline="")

        def polygon(points, fill, outline="#211626"):
            coords = [value for px, py in points for value in (round(x + px), round(y + py))]
            c.create_polygon(*coords, fill=fill, outline=outline, width=2 if outline else 0)

        def leg(phase, color, shine):
            swing = sin(phase)
            knee = (26 * swing, 23 - 8 * max(0, swing))
            fx = 43 * swing
            fy = 56 + bob - 23 * max(0, cos(phase))
            polygon([(-13, -4), (8, -4), (knee[0] + 8, knee[1]),
                     (fx + 6, fy - 8), (fx - 8, fy - 5),
                     (knee[0] - 8, knee[1] + 8), (-11, 14)], color)
            self.line(x + 2, y + 4, x + knee[0] + 3, y + knee[1],
                      x + fx + 1, y + fy - 10, color=shine, width=3)
            polygon([(fx - 8, fy - 10), (fx + 4, fy - 10), (fx + 15, fy - 4),
                     (fx + 17, fy + 2), (fx - 10, fy + 2)], "#f1d8ba")
            self.line(x + fx - 7, y + fy - 2, x + fx + 12, y + fy - 2, color="#f57d73", width=3)

        def arm(phase, back=False):
            swing = 20 * sin(phase)
            shoulder = (10, -44)
            elbow = (5 + swing, -20)
            hand = (22 + swing * 1.25, -34 - swing * .32)
            if self.mode == "won":
                elbow, hand = (25, -54), (40, -74)
            points = [coord for px, py in (shoulder, elbow, hand) for coord in (x + px, y + py)]
            self.line(*points, color="#211626", width=13)
            self.line(*points, color="#78223f" if back else "#c94765", width=9)
            hx, hy = hand
            polygon([(hx - 4, hy - 3), (hx + 4, hy - 5), (hx + 8, hy),
                     (hx + 3, hy + 5)], "#bb7759" if back else "#f2ad7e")

        leg(p + pi, "#282746", "#433b61")
        arm(p, True)
        leg(p, "#3b4160", "#637691")
        polygon([(-9, -5), (6, 2), (15, -16), (23, -39), (18, -54),
                 (3, -55), (-10, -46), (-18, -15)], "#a82e54")
        polygon([(-12, -37), (4, -44), (13, -36), (2, -28), (-13, -19)], "#e15869", "")
        pack = 3 * sin(p)
        polygon([(-9, -49), (-27, -48 + pack), (-38, -36 + pack),
                 (-40, -15 + pack), (-31, -6 + pack), (-17, -8), (-9, -24)], "#297a77")
        polygon([(-26, -42 + pack), (-34, -35 + pack), (-35, -22 + pack),
                 (-25, -20 + pack), (-20, -41 + pack)], "#64b5a1", "")
        self.line(x - 35, y - 19 + pack, x - 22, y - 16 + pack, color=GOLD, width=3)
        self.line(x - 13, y - 45, x + 6, y - 47, x + 5, y - 36,
                  x - 6, y - 21, color="#82d4ae", width=4)
        polygon([(10, -52), (14, -70), (30, -77), (42, -67), (42, -61),
                 (48, -56), (42, -53), (39, -45), (25, -44), (18, -50)], "#eda278")
        polygon([(14, -55), (8, -62), (12, -76), (23, -83),
                 (37, -82), (45, -73), (40, -66), (26, -67),
                 (23, -57), (19, -59)], "#272132")
        self.line(x + 35, y - 62, x + 40, y - 62, color="#382533", width=2)
        arm(p + pi)
        if self.mode == "running":
            for i in range(5):
                age = (p / (2 * pi) + i * .19) % 1
                c.create_oval(x - 20 - 73 * age, ground - 18 * age,
                              x - 15 - 72 * age, ground + 5 - 19 * age,
                              fill=("#e49d85" if age < .4 else "#875b66"), outline="")

    def hud(self):
        chase = self.chase
        self.rect(0, 0, WIDTH, 82, color=INK)
        self.rect(0, 80, WIDTH, 82, color="#9c385b")
        self.text(24, 27, "RAMVAN RUSH", GOLD, self.bold)
        self.text(25, 58, "ROSE HILL  /  LINCOLN CENTER", MUTED)
        minutes, seconds = divmod(ceil(DURATION - chase.elapsed), 60)
        stats = (("PACE", f"{round(chase.pace * 12):02d} WPM"),
                 ("GAP", f"{ceil(chase.gap):02d} m"),
                 ("DEPARTURE", f"{minutes}:{seconds:02d}"))
        for (label, value), x in zip(stats, (411, 568, 716)):
            self.text(x, 23, label, MUTED)
            color = RED if label == "DEPARTURE" and chase.elapsed > DURATION - 8 else CREAM
            self.text(x, 52, value, color, self.bold)
        self.text(976, 52, "ESC  Pause", MUTED, anchor="e")
        self.rect(0, 82, (1 - chase.elapsed / DURATION) * WIDTH, 86, color=GOLD)

    def typing_console(self, now):
        chase = self.chase
        self.rect(0, 520, WIDTH, HEIGHT, color=INK)
        self.rect(0, 520, WIDTH, 523, color=RED if now < self.error_until else "#a34062")
        self.text(26, 546, "TYPE THE PASSAGE", GOLD)
        if now < self.error_until:
            self.text(974, 546, "Try the highlighted character", RED, anchor="e")
        else:
            self.text(974, 546, "Match capitals and punctuation", MUTED, anchor="e")
        char_width = self.regular.measure("M")
        limit = int(948 / char_width)
        prompt = chase.prompt
        rows = []
        while len(prompt) > limit:
            end = prompt.rfind(" ", 0, limit)
            rows.append(prompt[:end + 1])
            prompt = prompt[end + 1:]
        rows.append(prompt)
        start = 0
        for y, row in zip((579, 610), rows):
            typed = max(0, min(len(row), chase.index - start))
            self.text(26, y, row[:typed], MINT, self.regular)
            x = 26 + char_width * typed
            if typed < len(row) and chase.index >= start:
                accent = RED if now < self.error_until else GOLD
                self.rect(x - 1, y - 13, x + char_width + 1, y + 13, color=accent)
                self.text(x, y, row[typed] if row[typed] != " " else "_", INK, self.regular)
                typed += 1
                x += char_width
            self.text(x, y, row[typed:], CREAM, self.regular)
            start += len(row)

    def overlay(self):
        modes = {
            "ready": ("LAST SHUTTLE", "RAMVAN RUSH", "Catch the shuttle before it leaves.",
                      "Copy each passage and aim for 90 WPM to close the gap.", "ENTER  /  START RUN"),
            "paused": ("CHASING THE RAM VAN", "PAUSED", "Your runner can wait here.",
                       "Press Escape or Enter to pick up where you left off.", "ENTER  /  RESUME"),
            "won": ("TICKET PUNCHED", "YOU MADE IT!", "Next stop, Lincoln Center.",
                    "Your backpack would like the window seat.", "ENTER  /  RUN AGAIN"),
            "lost": ("DEPARTED", "VAN MISSED", "The Ram Van is on its way to Lincoln Center.",
                     "Your backpack would like a lighter course load.", "ENTER  /  RETRY"),
        }
        badge, title, subtitle, details, button = modes[self.mode]
        self.rect(187, 143, 820, 429, color="#251325")
        self.rect(180, 136, 813, 422, color=INK)
        self.rect(180, 136, 813, 141, color=GOLD)
        self.text(500, 174, badge, GOLD, anchor="center")
        self.text(502, 239, title, "#823253", self.title, anchor="center")
        self.text(498, 235, title, CREAM, self.title, anchor="center")
        self.text(500, 294, subtitle, CREAM, self.bold, anchor="center")
        self.text(500, 328, details, MUTED, self.small, anchor="center")
        self.rect(366, 358, 634, 404, color=GOLD)
        self.text(500, 381, button, INK, anchor="center")
        if self.mode in ("won", "lost"):
            wpm = round(self.chase.correct * 12 / self.chase.elapsed)
            self.rect(268, 444, 732, 478, color=INK)
            self.text(500, 461,
                      f"{wpm} AVG WPM    {self.chase.accuracy}% ACCURACY    {ceil(self.chase.gap)} m GAP",
                      CREAM, anchor="center")

    def frame(self):
        now = perf_counter()
        dt = min(.10, now - self.last_frame)
        self.last_frame = now
        if self.mode == "running":
            self.chase.tick(dt)
            if self.chase.outcome:
                self.mode = self.chase.outcome
                self.finished_at = now
        if self.mode in ("ready", "running", "lost"):
            speed = self.chase.speed if self.mode == "running" else 2.7
            self.travel += speed * 20 * dt
            self.stride += (7 + speed * 1.35) * dt
        scene_time = now if self.mode != "paused" else self.paused_at
        self.canvas.delete("all")
        self.stage(scene_time - self.clock)
        self.hud()
        self.typing_console(now)
        if self.mode != "running":
            self.overlay()
        if self.mode != "paused":
            self.paused_at = now
        self.root.after(16, self.frame)


